SINA_SMART["hemato1-b9-b12"] = {"lecture":"hemato1-b9-b12","title":"Vitamin B9 and B12 metabolism","mapStatus":"auto: generated by universal.py from the lecture summary and key points; not human-reviewed","los":[{"id":"hemato1-b9-b12:e0","text":"B9 and B12: needed for DNA (not RNA) synthesis.","topic":"The big picture","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"hemato1-b9-b12:e1","text":"Deficiency: nucleo-cytoplasmic asynchrony → megaloblasts, macrocytic anaemia.","topic":"The big picture","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"hemato1-b9-b12:e2","text":"Folate: pteridine + PABA + glutamate; one-carbon transfer.","topic":"Vitamin B9 (folate)","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"hemato1-b9-b12:e3","text":"Folate sources: leafy vegetables, liver; heat-labile.","topic":"Vitamin B9 (folate)","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"hemato1-b9-b12:e4","text":"Needs 330 µg/day; 440 µg/day in pregnancy (neural tube defects).","topic":"Vitamin B9 (folate)","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"hemato1-b9-b12:e5","text":"Folate absorbed in duodenum/jejunum; circulates as 5-methyl-THF.","topic":"Vitamin B9 (folate)","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"hemato1-b9-b12:e6","text":"Methionine synthase (B12) frees THF → 5,10-methylene-THF → thymidylate synthase.","topic":"Vitamin B9 (folate)","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"hemato1-b9-b12:e10","text":"Causes: pernicious anaemia, gastrectomy, ileal disease, vegan diet.","topic":"Vitamin B12 (cobalamin)","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"hemato1-b9-b12:e7","text":"B12: cobalt corrin ring; only in animal foods.","topic":"Vitamin B12 (cobalamin)","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"hemato1-b9-b12:e8","text":"Intrinsic factor (parietal cells) → terminal ileum absorption; transcobalamin.","topic":"Vitamin B12 (cobalamin)","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"hemato1-b9-b12:e9","text":"B12 liver stores last years; deficiency → anaemia + neurological damage.","topic":"Vitamin B12 (cobalamin)","sec":2,"importance":"core","highYield":"insufficient-source"}],"vmap":{},"mlevel":{"3b6q30":"a","162qc4a":"a","1d9pl44":"a","ayxlwl":"a","6qg2ld":"a","7z145k":"a","1g9p4kl":"a","reygsy":"a","btq7bw":"a","fco14h":"a","md0oiu":"a","5e2wep":"a","1dbciy2":"a","1ysjzmd":"a"},"mapCounts":{"verified":0,"auto":14,"ambiguous":0,"missing":0},"mrules":[],"items":[],"experimental":[],"status":{},"difficulty":{},"expl":{"hemato1-b9-b12:e0":{"s":0,"u":["B9 and B12: needed for DNA (not RNA) synthesis.","Folic acid (vitamin B9) and cobalamin (vitamin B12) are essential for DNA synthesis (not RNA), so their deficiency hits rapidly dividing tissues first, especially the bone marrow."],"dp":[]},"hemato1-b9-b12:e1":{"s":0,"u":["Deficiency: nucleo-cytoplasmic asynchrony → megaloblasts, macrocytic anaemia.","Nuclear maturation is delayed while cytoplasmic maturation continues: nucleo-cytoplasmic asynchrony , producing large megaloblasts in the marrow and macrocytic (megaloblastic) anaemia , often with giant metamyelocytes and hypersegmented neutrophils."],"dp":[]},"hemato1-b9-b12:e2":{"s":1,"u":["Folate: pteridine + PABA + glutamate; one-carbon transfer.","Structure: a pteridine ring , para-aminobenzoic acid and one or more glutamate residues; folate transfers one-carbon (methyl) groups."],"dp":[]},"hemato1-b9-b12:e3":{"s":1,"u":["Folate sources: leafy vegetables, liver; heat-labile.","Sources : leafy vegetables (spinach, cauliflower) and liver; folates are destroyed by heat ."],"dp":[]},"hemato1-b9-b12:e4":{"s":1,"u":["Needs 330 µg/day; 440 µg/day in pregnancy (neural tube defects).","Needs : about 330 µg/day in adults, 440 µg/day in pregnancy (supplementation prevents neural tube defects)."],"dp":[]},"hemato1-b9-b12:e5":{"s":1,"u":["Folate absorbed in duodenum/jejunum; circulates as 5-methyl-THF.","It circulates as 5-methyl-THF (inactive) and is stored in the liver (a few milligrams, lasting only months).","Absorption in the duodenum and jejunum , impaired by coeliac disease and sprue."],"dp":[]},"hemato1-b9-b12:e6":{"s":1,"u":["Methionine synthase (B12) frees THF → 5,10-methylene-THF → thymidylate synthase.","In cells, B12-dependent methionine synthase converts 5-methyl-THF to THF (turning homocysteine into methionine); THF becomes 5,10-methylene-THF , used by thymidylate synthase to make dTMP from dUMP for DNA."],"dp":[]},"hemato1-b9-b12:e10":{"s":2,"u":["Causes: pernicious anaemia, gastrectomy, ileal disease, vegan diet.","Causes : pernicious anaemia (autoimmune loss of intrinsic factor), gastrectomy, ileal resection or disease, strict vegan diet."],"dp":[]},"hemato1-b9-b12:e7":{"s":2,"u":["B12: cobalt corrin ring; only in animal foods.","A tetrapyrrole (corrin) ring around a cobalt atom ; forms include methylcobalamin, adenosylcobalamin, hydroxocobalamin and cyanocobalamin.","Found only in animal foods (meat, liver, eggs, dairy)."],"dp":[]},"hemato1-b9-b12:e8":{"s":2,"u":["Intrinsic factor (parietal cells) → terminal ileum absorption; transcobalamin.","In the stomach it binds intrinsic factor , secreted by parietal cells , and the complex is absorbed in the terminal ileum ; in blood it is carried by transcobalamin .","Causes : pernicious anaemia (autoimmune loss of intrinsic factor), gastrectomy, ileal resection or disease, strict vegan diet."],"dp":[]},"hemato1-b9-b12:e9":{"s":2,"u":["B12 liver stores last years; deficiency → anaemia + neurological damage.","The liver stores several milligrams , enough for years, so deficiency develops slowly.","It is a cofactor of methionine synthase (DNA synthesis) and of myelin metabolism, so deficiency causes megaloblastic anaemia and neurological damage (subacute combined degeneration of the cord)."],"dp":[{"h":"Why a gastrectomy leads to B12 deficiency years later","t":"After removal of the stomach, parietal cells no longer secrete intrinsic factor, so dietary B12 cannot be absorbed in the ileum. Because the liver holds enough B12 for several years, blood counts stay normal for a long time before macrocytic anaemia and nerve damage appear. Patients therefore receive lifelong B12 injections, bypassing the gut. Source: the lecture's B12 metabolism and causes of deficiency."}]}},"meta":{"3b6q30":{"a":"recall","vg":"hemato1-b9-b12:e0/recall/1"},"162qc4a":{"a":"recall","vg":"hemato1-b9-b12:e9/recall/1"},"1d9pl44":{"a":"recall","vg":"hemato1-b9-b12:e3/recall/1"},"ayxlwl":{"a":"recall","vg":"hemato1-b9-b12:e4/recall/1"},"6qg2ld":{"a":"recall","vg":"hemato1-b9-b12:e4/recall/2"},"7z145k":{"a":"recall","vg":"hemato1-b9-b12:e5/recall/1"},"1g9p4kl":{"a":"recall","vg":"hemato1-b9-b12:e5/recall/2"},"reygsy":{"a":"recall","vg":"hemato1-b9-b12:e6/recall/1"},"btq7bw":{"a":"recall","vg":"hemato1-b9-b12:e0/recall/2"},"fco14h":{"a":"recall","vg":"hemato1-b9-b12:e8/recall/1"},"md0oiu":{"a":"recall","vg":"hemato1-b9-b12:e8/recall/2"},"5e2wep":{"a":"relationship","vg":"hemato1-b9-b12:e9/relationship/1"},"1dbciy2":{"a":"relationship","vg":"hemato1-b9-b12:e8/relationship/1"},"1ysjzmd":{"a":"recall","vg":"hemato1-b9-b12:e9/recall/2"}},"explRev":"71fea3c85d8d"};
